USE enlazate;
CREATE TABLE digital_pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NULL, qr_code_id BIGINT UNSIGNED NULL, slug VARCHAR(190) NOT NULL UNIQUE, page_type ENUM('menu','wifi','contact','reviews','maps','whatsapp') NOT NULL, title VARCHAR(190) NOT NULL, subtitle VARCHAR(255) NULL, logo_url VARCHAR(500) NULL, cover_url VARCHAR(500) NULL, content JSON NULL, is_public TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY(qr_code_id) REFERENCES qr_codes(id) ON DELETE SET NULL);
CREATE TABLE digital_page_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(page_id) REFERENCES digital_pages(id) ON DELETE CASCADE);
CREATE TABLE digital_page_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(190) NOT NULL, description TEXT NULL, price_dop DECIMAL(12,2) NULL, image_url VARCHAR(500) NULL, sort_order INT NOT NULL DEFAULT 0, is_available TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(category_id) REFERENCES digital_page_categories(id) ON DELETE CASCADE);
CREATE TABLE nfc_tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NULL, qr_code_id BIGINT UNSIGNED NULL, uid VARCHAR(120) NOT NULL UNIQUE, label VARCHAR(190) NOT NULL, status ENUM('unprogrammed','active','paused','retired') NOT NULL DEFAULT 'unprogrammed', notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY(qr_code_id) REFERENCES qr_codes(id) ON DELETE SET NULL);
